-- ============================================
-- LUMA — Thème 2 (Rendez-vous amoureux) : 3 scénarios COURTS x4
-- ============================================


update scenarios set content = '{"characters": {"alex": "Alex"}, "start_node": "n1", "nodes": {"n1": {"speaker": "narrator", "text": "You see Alex''s profile: loves hiking, cooking, and dogs. Time to write a first message.", "text_fr": "Vous voyez le profil d''Alex : adore la randonnée, la cuisine et les chiens. Il est temps d''écrire un premier message.", "choices": [{"text": "Hey! I noticed you love hiking — any favorite trails?", "text_fr": "Salut ! J''ai vu que tu adores la randonnée — un sentier préféré ?", "next": "n2"}, {"text": "Your profile says you cook — what''s your specialty?", "text_fr": "Ton profil dit que tu cuisines — c''est quoi ta spécialité ?", "next": "n2b"}, {"text": "Hi, cute dog in your photos! What''s their name?", "text_fr": "Salut, chien mignon sur tes photos ! Il s''appelle comment ?", "next": "n2c"}]}, "n2": {"speaker": "alex", "text": "Hey! Yes, I love the coastal trail near the lighthouse. Do you hike too?", "text_fr": "Salut ! Oui, j''adore le sentier côtier près du phare. Tu fais de la randonnée aussi ?", "choices": [{"text": "I do! Mostly on weekends when I have time.", "text_fr": "Oui ! Surtout le week-end quand j''ai le temps.", "next": "n3"}, {"text": "Not much, but I''d love to try that trail sometime.", "text_fr": "Pas beaucoup, mais j''aimerais bien essayer ce sentier un jour.", "next": "n3"}]}, "n2b": {"speaker": "alex", "text": "Haha, I make a mean pasta carbonara. Do you cook much?", "text_fr": "Haha, je fais un excellent carbonara. Tu cuisines beaucoup ?", "choices": [{"text": "I try! Not as fancy as carbonara though.", "text_fr": "J''essaie ! Pas aussi élaboré que le carbonara par contre.", "next": "n3"}, {"text": "Not really, but I''m a great taste-tester.", "text_fr": "Pas vraiment, mais je suis un excellent goûteur.", "next": "n3"}]}, "n2c": {"speaker": "alex", "text": "That''s Bailey! He''s a golden retriever, total goofball. Do you have pets?", "text_fr": "C''est Bailey ! Un golden retriever, un vrai clown. Tu as des animaux ?", "choices": [{"text": "No pets, but I love dogs, Bailey looks adorable!", "text_fr": "Pas d''animaux, mais j''adore les chiens, Bailey a l''air adorable !", "next": "n3"}, {"text": "I have a cat who''s basically the opposite personality.", "text_fr": "J''ai un chat qui a une personnalité totalement opposée.", "next": "n3"}]}, "n3": {"speaker": "alex", "text": "Nice! So what do you like to do for fun besides that?", "text_fr": "Cool ! Sinon tu fais quoi pour t''amuser à part ça ?", "choices": [{"text": "I love trying new restaurants and reading.", "text_fr": "J''aime essayer de nouveaux restaurants et lire.", "next": "n4"}, {"text": "Mostly gaming and watching movies, pretty chill.", "text_fr": "Surtout jouer aux jeux vidéo et regarder des films, assez tranquille.", "next": "n4"}]}, "n4": {"speaker": "alex", "text": "That sounds fun! I''d love to chat more — are you free this week?", "text_fr": "Ça a l''air sympa ! J''aimerais bien discuter plus — t''es libre cette semaine ?", "choices": [{"text": "Yeah, I''d love that! How about coffee?", "text_fr": "Ouais, avec plaisir ! Un café ça te dit ?", "next": "n5"}, {"text": "Definitely, let''s keep chatting here for now though.", "text_fr": "Carrément, continuons à discuter ici pour l''instant par contre.", "next": "n5b"}]}, "n5": {"speaker": "alex", "text": "Coffee sounds perfect! I know a great little place downtown.", "text_fr": "Un café ça a l''air parfait ! Je connais un chouette endroit en centre-ville.", "choices": [{"text": "Sounds great, send me the details!", "text_fr": "Ça a l''air super, envoie-moi les détails !", "next": "end_date"}]}, "n5b": {"speaker": "alex", "text": "Sure, no rush! I''m enjoying getting to know you first.", "text_fr": "Bien sûr, aucune urgence ! J''aime bien apprendre à te connaître d''abord.", "choices": [{"text": "Same here, this is fun.", "text_fr": "Pareil pour moi, c''est sympa.", "next": "end_slow"}]}, "end_date": {"speaker": "alex", "text": "Perfect, looking forward to it!", "text_fr": "Parfait, j''ai hâte !", "end": true, "ending_label": "Rendez-vous fixé rapidement ☕✨"}, "end_slow": {"speaker": "alex", "text": "Great, let''s see where this goes!", "text_fr": "Super, voyons où ça nous mène !", "end": true, "ending_label": "Une connexion qui prend son temps 💬"}}}'::jsonb, is_playable = true
where title = 'Premier message sur une appli de rencontre'
  and theme_id = (select id from scenario_themes where position = 2 and language_id = (select id from languages where code = 'en'));


update scenarios set content = '{"characters": {"alex": "Alex"}, "start_node": "n1", "nodes": {"n1": {"speaker": "alex", "text": "So, where should we meet? I''m flexible on time too.", "text_fr": "Alors, on se voit où ? Je suis flexible sur l''heure aussi.", "choices": [{"text": "How about that café you mentioned, Saturday afternoon?", "text_fr": "Le café dont tu parlais, samedi après-midi, ça te dit ?", "next": "n2"}, {"text": "I know a nice spot near the park, if you''re open to it.", "text_fr": "Je connais un bel endroit près du parc, si ça te tente.", "next": "n2b"}]}, "n2": {"speaker": "alex", "text": "Saturday works great for me! Does 2pm sound good?", "text_fr": "Samedi ça me va super bien ! 14h ça te va ?", "choices": [{"text": "2pm is perfect, see you then!", "text_fr": "14h c''est parfait, à samedi !", "next": "n3"}, {"text": "Could we do a bit later, like 3pm?", "text_fr": "On pourrait faire un peu plus tard, genre 15h ?", "next": "n2c"}]}, "n2b": {"speaker": "alex", "text": "That sounds lovely! What day works for you?", "text_fr": "Ça a l''air adorable ! Quel jour ça te va ?", "choices": [{"text": "Saturday afternoon would be great.", "text_fr": "Samedi après-midi serait parfait.", "next": "n2"}, {"text": "Sunday morning, if that works for you?", "text_fr": "Dimanche matin, si ça te va ?", "next": "n2d"}]}, "n2c": {"speaker": "alex", "text": "3pm works too, no problem at all!", "text_fr": "15h ça marche aussi, aucun problème !", "choices": [{"text": "Great, see you at 3!", "text_fr": "Super, à 15h !", "next": "n3"}]}, "n2d": {"speaker": "alex", "text": "Sunday morning sounds nice actually, let''s do 10am!", "text_fr": "Dimanche matin ça a l''air sympa en fait, faisons 10h !", "choices": [{"text": "Perfect, 10am it is.", "text_fr": "Parfait, va pour 10h.", "next": "n3"}]}, "n3": {"speaker": "alex", "text": "Great, I''ll send you the exact address closer to the day.", "text_fr": "Super, je t''envoie l''adresse exacte plus près du jour.", "choices": [{"text": "Sounds good, looking forward to it!", "text_fr": "Ça marche, j''ai hâte !", "next": "n4"}, {"text": "Perfect — how will I recognize you?", "text_fr": "Parfait — comment je te reconnais ?", "next": "n4b"}]}, "n4": {"speaker": "alex", "text": "Me too! This is exciting.", "text_fr": "Moi aussi ! C''est excitant.", "choices": [{"text": "Definitely, see you soon!", "text_fr": "Carrément, à bientôt !", "next": "end_confirmed"}]}, "n4b": {"speaker": "alex", "text": "Ha, good question — I''ll wear a blue jacket, and I''m tall with curly hair!", "text_fr": "Ha, bonne question — je porterai une veste bleue, et je suis grand avec des cheveux bouclés !", "choices": [{"text": "Perfect, I''ll keep an eye out!", "text_fr": "Parfait, je vais garder l''œil ouvert !", "next": "end_confirmed"}]}, "end_confirmed": {"speaker": "alex", "text": "Can''t wait! See you then.", "text_fr": "J''ai hâte ! À bientôt.", "end": true, "ending_label": "Rendez-vous confirmé avec les détails 📍"}}}'::jsonb, is_playable = true
where title = 'Fixer le lieu et l''''heure'
  and theme_id = (select id from scenario_themes where position = 2 and language_id = (select id from languages where code = 'en'));
